<?php
declare(strict_types=1);
namespace Tests\Integration\Repositories;
use App\Core\MigrationRunner; use App\Repositories\PdoAdministratorDashboardMetricsRepository; use DateTimeImmutable; use PHPUnit\Framework\Attributes\Group; use Tests\Support\DatabaseTestCase; use Tests\Support\NotificationFixture;
#[Group('database')] final class AdministratorDashboardMetricsRepositoryTest extends DatabaseTestCase
{ private PdoAdministratorDashboardMetricsRepository $repository; private int $owner; private int $other;
 protected function setUp():void { parent::setUp(); (new MigrationRunner($this->connection,dirname(__DIR__,3).'/database/migrations'))->migrate(); $this->owner=NotificationFixture::insertAdministrator($this->connection,'dashboard-owner'); $this->other=NotificationFixture::insertAdministrator($this->connection,'dashboard-other'); $this->repository=new PdoAdministratorDashboardMetricsRepository($this->connection); }
 public function testEmptyDatabaseReturnsZeroAggregates():void{$m=$this->metrics();foreach(['activeRooms','occupiedRooms','availableRooms','arrivalsToday','departuresToday','pendingBookings','confirmedBookings','pendingPaymentReviews','pendingReviewModeration','unreadNotifications'] as $method)self::assertSame(0,$m->$method());}
 public function testMetricsUseAuthoritativeStatusesBoundariesAndNotificationOwnership():void { $this->connection->exec("INSERT INTO room_types (name,slug,base_price,capacity_adults,capacity_children,is_active,created_at,updated_at) VALUES ('Type','type','100.00',2,0,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$type=(int)$this->connection->lastInsertId(); $this->room($type,'active','2026-01-01 00:00:00');$this->room($type,'inactive','2026-01-01 00:00:00',false,'inactive');$this->room($type,'deleted','2026-01-01 00:00:00',true); $pending=$this->booking('pending','2026-08-01','2026-08-02');$confirmed=$this->booking('confirmed','2026-07-31','2026-08-01');$checked=$this->booking('checked_in','2026-08-01','2026-08-02');$this->connection->exec("INSERT INTO booking_rooms (booking_id,room_id,price_per_night,nights,subtotal,created_at) VALUES ($checked,1,'100.00',1,'100.00',UTC_TIMESTAMP())"); $this->connection->exec("INSERT INTO payment_methods (name,instructions,requires_proof,is_active,created_at,updated_at) VALUES ('Dashboard Test Method','Test-only instructions',0,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$method=(int)$this->connection->lastInsertId();$this->connection->exec("INSERT INTO payments (booking_id,payment_method_id,currency,amount,payment_status,created_at,updated_at) VALUES ($pending,$method,'NPR','100.00','submitted',UTC_TIMESTAMP(),UTC_TIMESTAMP())"); $this->connection->exec("INSERT INTO review_invitations (booking_id,token_hash,expires_at,created_at) VALUES ($pending,'".str_repeat('a',64)."','2026-09-01 00:00:00',UTC_TIMESTAMP())");$inv=(int)$this->connection->lastInsertId();$this->connection->exec("INSERT INTO reviews (booking_id,review_invitation_id,guest_name_snapshot,rating,comment,review_status,created_at,updated_at) VALUES ($pending,$inv,'Guest',5,'Fine','pending',UTC_TIMESTAMP(),UTC_TIMESTAMP())"); foreach([$this->owner,$this->other] as $u)$this->connection->exec("INSERT INTO notifications (user_id,type,title,message,created_at) VALUES ($u,'test','Title','Message',UTC_TIMESTAMP())");$m=$this->metrics();self::assertSame(1,$m->activeRooms());self::assertSame(1,$m->occupiedRooms());self::assertSame(0,$m->availableRooms());self::assertSame(2,$m->arrivalsToday());self::assertSame(1,$m->departuresToday());self::assertSame(1,$m->pendingBookings());self::assertSame(1,$m->confirmedBookings());self::assertSame(1,$m->pendingPaymentReviews());self::assertSame(1,$m->pendingReviewModeration());self::assertSame(1,$m->unreadNotifications()); }
 public function testRoomEligibilityAndDistinctOccupiedRoomsAreExplicit():void{$type=$this->type();$this->room($type,'active-a',null,false,'active');$this->room($type,'active-b',null,false,'active');$this->room($type,'maintenance',null,false,'maintenance');$this->room($type,'inactive',null,false,'inactive');$this->room($type,'deleted','2026-08-01 00:00:00',true,'active');$one=$this->booking('checked_in','2026-08-01','2026-08-02');$two=$this->booking('checked_in','2026-08-01','2026-08-02');$deletedBooking=$this->booking('checked_in','2026-08-01','2026-08-02');$this->connection->exec("UPDATE bookings SET deleted_at = '2026-08-01 00:00:00' WHERE id = $deletedBooking");foreach([$one,$two,$deletedBooking] as $booking)$this->connection->exec("INSERT INTO booking_rooms (booking_id,room_id,price_per_night,nights,subtotal,created_at) VALUES ($booking,1,'100.00',1,'100.00',UTC_TIMESTAMP())");$m=$this->metrics();self::assertSame(2,$m->activeRooms());self::assertSame(1,$m->occupiedRooms());self::assertSame(1,$m->availableRooms());}
 public function testArrivalAndDepartureDateBoundariesAreInclusiveExclusive():void{foreach([['2026-07-31','2026-08-01'],['2026-08-01','2026-08-02'],['2026-08-01','2026-08-02'],['2026-08-02','2026-08-03']] as [$in,$out])$this->booking('cancelled',$in,$out);$m=$this->metrics();self::assertSame(2,$m->arrivalsToday());self::assertSame(1,$m->departuresToday());}
 public function testOnlyPendingAndConfirmedBookingStatusesAreCounted():void{foreach(['pending','confirmed','checked_in','checked_out','cancelled','rejected'] as $status)$this->booking($status,'2026-07-30','2026-07-31');$m=$this->metrics();self::assertSame(1,$m->pendingBookings());self::assertSame(1,$m->confirmedBookings());}
 public function testPaymentReviewReviewModerationAndNotificationFiltersAreExplicit():void{$booking=$this->booking('pending','2026-08-01','2026-08-02');$this->connection->exec("INSERT INTO payment_methods (name,instructions,requires_proof,is_active,created_at,updated_at) VALUES ('Dashboard Test Method','Test-only instructions',0,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$method=(int)$this->connection->lastInsertId();foreach(['pending','submitted','verified','rejected','refunded'] as $status)$this->connection->exec("INSERT INTO payments (booking_id,payment_method_id,currency,amount,payment_status,created_at,updated_at) VALUES ($booking,$method,'NPR','100.00','$status',UTC_TIMESTAMP(),UTC_TIMESTAMP())");foreach(['pending','approved','rejected'] as $status){$reviewBooking=$this->booking('checked_out','2026-07-30','2026-07-31');$token=bin2hex(random_bytes(32));$this->connection->exec("INSERT INTO review_invitations (booking_id,token_hash,expires_at,created_at) VALUES ($reviewBooking,'$token','2026-09-01',UTC_TIMESTAMP())");$inv=(int)$this->connection->lastInsertId();$moderation=$status==='pending'?'NULL,NULL,NULL':$this->owner.",UTC_TIMESTAMP(),'Review decision'";$this->connection->exec("INSERT INTO reviews (booking_id,review_invitation_id,guest_name_snapshot,rating,comment,review_status,moderated_by,moderated_at,moderation_note,created_at,updated_at) VALUES ($reviewBooking,$inv,'Guest',5,'Fine','$status',$moderation,UTC_TIMESTAMP(),UTC_TIMESTAMP())");}NotificationFixture::insert($this->connection,$this->owner);NotificationFixture::insert($this->connection,$this->owner,['read_at'=>'2026-08-01 07:00:00']);NotificationFixture::insert($this->connection,$this->other);NotificationFixture::insert($this->connection,$this->other,['read_at'=>'2026-08-01 07:00:00']);$m=$this->metrics();self::assertSame(1,$m->pendingPaymentReviews());self::assertSame(1,$m->pendingReviewModeration());self::assertSame(1,$m->unreadNotifications());}
 private function metrics():\App\Models\AdministratorDashboardMetrics{return $this->repository->metrics($this->owner,new DateTimeImmutable('2026-07-31 18:15:00 UTC'),new DateTimeImmutable('2026-08-01 18:15:00 UTC'));}
 private function type():int{$suffix=bin2hex(random_bytes(4));$this->connection->exec("INSERT INTO room_types (name,slug,base_price,capacity_adults,capacity_children,is_active,created_at,updated_at) VALUES ('Type $suffix','type-$suffix','100.00',2,0,1,UTC_TIMESTAMP(),UTC_TIMESTAMP())");return(int)$this->connection->lastInsertId();}
 private function room(int $type,string $suffix,?string $deleted,bool $isDeleted=false,string $status='active'):void{$s=$this->connection->prepare('INSERT INTO rooms (room_type_id,room_number,name,slug,price_per_night,capacity_adults,capacity_children,operational_status,is_published,created_at,updated_at,deleted_at) VALUES (:t,:number,:name,:slug,\'100.00\',2,0,:status,1,UTC_TIMESTAMP(),UTC_TIMESTAMP(),:d)');$s->execute(['t'=>$type,'number'=>$suffix,'name'=>$suffix,'slug'=>$suffix,'status'=>$status,'d'=>$isDeleted?$deleted:null]);}
 private function booking(string $status,string $in,string $out):int{$s=$this->connection->prepare("INSERT INTO bookings (booking_reference,guest_full_name,guest_email,guest_phone,check_in,check_out,adults,children,currency,room_amount,total_amount,booking_status,terms_accepted_at,confirmation_deadline_at,created_at,updated_at) VALUES (:r,'Guest','guest@example.test','000',:i,:o,1,0,'NPR','100.00','100.00',:s,UTC_TIMESTAMP(),'2026-08-10 00:00:00',UTC_TIMESTAMP(),UTC_TIMESTAMP())");$s->execute(['r'=>strtoupper($status).bin2hex(random_bytes(4)),'i'=>$in,'o'=>$out,'s'=>$status]);return(int)$this->connection->lastInsertId();}}


